<?php
namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller;use App\Http\Requests\Api\ControllerRequest;use App\Http\Resources\ControllerResource;use App\Models\TnController;use App\Repositories\ControllerRepository;use App\Services\CrudService;
class ControllerController extends Controller {private CrudService $service;public function __construct(ControllerRepository $r){$this->service=new CrudService($r);}public function index(){return ControllerResource::collection($this->service->all(['machine','devices']));}public function store(ControllerRequest $r){$d=$r->validated()+['control_model'=>$r->input('control_model','fixed')];return (new ControllerResource($this->service->create($d)))->response()->setStatusCode(201);}public function show(TnController $controller){return new ControllerResource($controller->load('machine','devices'));}public function update(ControllerRequest $r,TnController $controller){return new ControllerResource($this->service->update($controller,$r->validated()));}public function destroy(TnController $controller){$this->service->delete($controller);return response()->noContent();}}
